select case when duration_sec >= 458 then 'high' when duration_sec >= 230 then 'mid' else 'low' end as duration_sec_bucket, sum(duration_sec) as total_duration_sec, dense_rank() over (order by sum(duration_sec) desc) as rnk from web_events group by case when duration_sec >= 458 then 'high' when duration_sec >= 230 then 'mid' else 'low' end order by duration_sec_bucket, total_duration_sec desc
